import 'package:flutter/material.dart';
import '../services/krevzy_social_settings_service.dart';
class AppWebsitePermissionsScreen extends StatefulWidget{const AppWebsitePermissionsScreen({super.key});@override State<AppWebsitePermissionsScreen>createState()=>_AppWebsitePermissionsScreenState();}
class _AppWebsitePermissionsScreenState extends State<AppWebsitePermissionsScreen>{final Map<String,bool> permissions={'Camera':true,'Microphone':true,'Photos and media':true,'Location':false,'Notifications':true};bool loading=true;String _key(String k)=>'permission_${k.toLowerCase().replaceAll(' ','_')}';@override void initState(){super.initState();_load();}Future<void>_load()async{try{final d=await KrevzySocialSettingsService.getSettings();if(!mounted)return;setState((){for(final k in permissions.keys){permissions[k]=d[_key(k)]as bool? ?? permissions[k]!;}loading=false;});}catch(e){if(mounted){setState(()=>loading=false);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Unable to load permissions: $e')));}}}Future<void>setv(String k,bool v)async{final old=permissions[k]!;setState(()=>permissions[k]=v);try{await KrevzySocialSettingsService.setValue(_key(k),v);}catch(e){if(mounted){setState(()=>permissions[k]=old);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Unable to save: $e')));}}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('App and website permissions')),body:loading?const Center(child:CircularProgressIndicator()):ListView(children:[const ListTile(title:Text('Permissions'),subtitle:Text('Manage KREVZY feature preferences. Device-level permission prompts are controlled by your operating system.')),...permissions.entries.map((e)=>SwitchListTile(title:Text(e.key),value:e.value,onChanged:(v)=>setv(e.key,v))),const Divider(),const ListTile(leading:Icon(Icons.link_outlined),title:Text('Connected apps and websites'),subtitle:Text('No connected apps are currently registered.'))]));}
